    ('3dc1cf81-9fff-4254-840c-c848abfb998a', 'organization_categories', 'SPACELINX', 'organization_categories', '[{"name":"Government Space Agency","description":"National and international agencies responsible for space exploration, research, scientific missions, and regulatory oversight (e.g., NASA, ESA, ISRO, JAXA, CNSA)."},{"name":"Commercial Space Businesses","description":"Private companies offering space-related products and services to non-governmental customers. This is the fastest-growing segment."},{"name":"National Security/Defense","description":"Organizations (both government and private contractors) involved in military and intelligence space operations, including surveillance, communication, and defense systems."},{"name":"Civil Space","description":"Non-defense government activities, including managing satellites, conducting research, and exploring the solar system."},{"name":"Spacecraft/Satellite Manufacturing","description":"Companies designing, developing, and producing satellites (ee.g., communication satellites, Earth observation satellites, navigation satellites), probes, and other spacecraft. This also includes miniature satellites like CubeSats, micro-satellites, and nano-satellites."},{"name":"Launch Vehicle Manufacturing & Launch Services","description":"Companies that build rockets and provide launch services to put satellites and spacecraft into orbit (e.g., orbital, suborbital). This includes traditional rockets and emerging reusable launch vehicles."},{"name":"Propulsion Systems","description":"Developers and manufacturers of rocket engines, thrusters, and other in-space propulsion solutions."},{"name":"Space Component Manufacturers","description":"Suppliers of specialized components, subsystems, and materials for spacecraft and launch vehicles (e.g., electronics, optics, advanced materials, sensors, communication systems, power systems, guidance systems)."},{"name":"Ground Segment Infrastructure","description":"Companies providing ground stations, telemetry, tracking and command (TT&C) systems, data processing facilities, and terrestrial connectivity to support satellite operations."},{"name":"Satellite Operators","description":"Companies that own and operate satellites, leasing or selling satellite capacity (bandwidth, data) for various applications."},{"name":"In-Orbit Services","description":"Companies offering services to satellites in orbit, such as refueling, repairs, upgrades, and debris removal."},{"name":"Space Situational Awareness (SSA) & Debris Management","description":"Companies focused on tracking objects in space, predicting collisions, and developing solutions for space debris."},{"name":"Satellite Communications (SatCom)","description":"Providers of satellite-based communication services (e.g., broadband internet, mobile communications, broadcasting, IoT connectivity, M2M)."},{"name":"Earth Observation (EO) & Remote Sensing","description":"Companies using satellite imagery and data for environmental monitoring, agriculture, urban planning, disaster response, mapping, and intelligence."},{"name":"Positioning, Navigation, and Timing (PNT)","description":"Providers of satellite-based navigation services (e.g., GNSS, GPS) for various commercial and strategic applications."},{"name":"Value-Added Services","description":"Companies that process and transform raw satellite data and signals into readily usable information and specialized solutions for various industries. This includes geospatial intelligence, climate monitoring, and resource management."},{"name":"Consumer Devices & Equipment","description":"Manufacturers of devices and equipment that utilize satellite services (e.g., satellite TV receivers, GNSS equipment, mobile satellite terminals)."},{"name":"Space Tourism","description":"Companies offering suborbital and orbital spaceflights for private individuals."},{"name":"Space Manufacturing (In-Space Production)","description":"Companies developing technologies and processes for manufacturing products in the microgravity environment of space (e.g., advanced materials, pharmaceuticals, 3D printing)."},{"name":"Space Mining (In-Situ Resource Utilization - ISRU)","description":"Companies exploring the extraction of resources (water, minerals, metals) from celestial bodies like the Moon and asteroids."},{"name":"Space Habitats & Infrastructure Development","description":"Companies designing and building commercial space stations, lunar bases, and other off-world habitats."},{"name":"Space Robotics","description":"Developers of robotic systems for in-space assembly, maintenance, and exploration."},{"name":"Space Energy","description":"Concepts and technologies related to generating and transmitting energy in space (e.g., space-based solar power)."},{"name":"Space Logistics & Transportation","description":"Companies focused on efficient in-space movement of goods and people beyond launch."},{"name":"Space Finance & Insurance","description":"Financial institutions and insurance providers specializing in the unique risks and investments of the space sector."},{"name":"Space Education & Training","description":"Organizations offering education, training, and simulation programs for aspiring astronauts, engineers, and space professionals."},{"name":"Space Law & Policy","description":"Consultancies and organizations specializing in legal and policy frameworks for space activities."},{"name":"Space Advocacy Organizations","description":"Non-profits and trade associations that advocate for policies and initiatives supporting the space industry."}]', 'charan@xdlinx.space', 'Organization Categories'),
